//! 🏛️ Spatial hierarchy, physical elements, geometry identities and typed property relationships.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use super::{SemioModelSnapshot,SpatialNode,SpatialKind,SemioModelElement,ElementClass,GeometryRef,PropertySet,Property,PsetValue,ModelRelation,RelationKind,SemioTransform,SemioPoint3,SemioQuaternion};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,reconstruct_text},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
fn number(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|error|error.to_string())}
fn identity<'a>(row:impl std::borrow::Borrow<SqliteRow<'a>>,columns:usize)->Result<(),String>{let row=*row.borrow();if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=columns{Err("invalid Semio model row identity or columns".into())}else{Ok(())}}
fn optional_integer(row:SqliteRow<'_>,index:usize)->Result<Option<i64>,String>{if row.is_null(index)?{Ok(None)}else{row.integer(index).map(Some)}}
fn ordered<'a>(mut rows:Vec<SqliteRow<'a>>,column:usize)->Result<Vec<SqliteRow<'a>>,String>{rows.sort_by_key(|row|row.integer(column).unwrap_or(-1));for(ordinal,row)in rows.iter().enumerate(){if row.integer(column)?!=number(ordinal)?{return Err("Semio model ordinals must be contiguous".into());}}Ok(rows)}
fn rows<'a>(db:&'a SqliteDatabase,table:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,String>{let mut result=BTreeMap::new();for(count,row)in float_rows(db,table,control)?.into_iter().enumerate(){identity(row,columns)?;if result.insert(row.rowid,row).is_some(){return Err("duplicate Semio model row identity".into());}if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn cycles(parents:&BTreeMap<i64,Option<i64>>,control:&mut SqliteSnapshotControl<'_>,phase:SqliteSnapshotPhase)->Result<(),String>{let mut marks=BTreeMap::new();let mut count=0;for &root in parents.keys(){let mut path=Vec::new();let mut current=Some(root);while let Some(id)=current{match marks.get(&id){Some(2)=>break,Some(1)=>return Err("cyclic Semio model spatial hierarchy".into()),_=>{}}marks.insert(id,1);path.push(id);current=*parents.get(&id).ok_or("dangling Semio model spatial parent")?;count+=1;if count%256==0{control.checkpoint(phase,0,0)?;}}for id in path{marks.insert(id,2);}}Ok(())}
fn class(value:&ElementClass)->(&'static str,Option<&str>){match value{ElementClass::Wall=>("wall",None),ElementClass::Slab=>("slab",None),ElementClass::Column=>("column",None),ElementClass::Beam=>("beam",None),ElementClass::Door=>("door",None),ElementClass::Window=>("window",None),ElementClass::Roof=>("roof",None),ElementClass::Stair=>("stair",None),ElementClass::Furniture=>("furniture",None),ElementClass::Other{name}=>("other",Some(name))}}
fn relation(value:&RelationKind)->(&'static str,Option<&str>){match value{RelationKind::Aggregates=>("aggregates",None),RelationKind::ContainedIn=>("contained_in",None),RelationKind::ConnectsTo=>("connects_to",None),RelationKind::FillsVoid=>("fills_void",None),RelationKind::VoidsElement=>("voids_element",None),RelationKind::Other{label}=>("other",Some(label))}}
fn placement(id:i64,t:SemioTransform,p:&mut Projection<'_,'_>)->Result<(),String>{p.insert_key_float("semio_model_placement",id,&[Cell::Real(t.translation.x),Cell::Real(t.translation.y),Cell::Real(t.translation.z),Cell::Real(t.rotation.x),Cell::Real(t.rotation.y),Cell::Real(t.rotation.z),Cell::Real(t.rotation.w),Cell::Real(t.scale.x),Cell::Real(t.scale.y),Cell::Real(t.scale.z)])}
fn restore_placement(row:SqliteRow<'_>)->Result<SemioTransform,String>{Ok(SemioTransform{translation:SemioPoint3{x:row.real(1)?,y:row.real(2)?,z:row.real(3)?},rotation:SemioQuaternion{x:row.real(4)?,y:row.real(5)?,z:row.real(6)?,w:row.real(7)?},scale:SemioPoint3{x:row.real(8)?,y:row.real(9)?,z:row.real(10)?}})}
impl ArtifactSqliteSnapshot for SemioModelSnapshot{
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="model"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_model_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
let count=self.spatial.len().checked_add(self.elements.len()).ok_or("Semio model entity count overflow")?;control.check_rows(count.checked_add(1).ok_or("Semio model entity count overflow")?)?;let mut entities=BTreeMap::new();let mut spatial_ids=BTreeMap::new();for(ordinal,node)in self.spatial.iter().enumerate(){let id=number(ordinal+1)?;if entities.insert(node.id.as_str(),id).is_some(){return Err("duplicate Semio model native identity".into());}spatial_ids.insert(node.id.as_str(),id);if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;}}for(ordinal,element)in self.elements.iter().enumerate(){if entities.insert(element.id.as_str(),number(self.spatial.len()+ordinal+1)?).is_some(){return Err("duplicate Semio model native identity".into());}if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;}}
let mut parents=BTreeMap::new();for node in &self.spatial{parents.insert(*spatial_ids.get(node.id.as_str()).ok_or("missing Semio spatial identity")?,match &node.parent_id{None=>None,Some(id)=>Some(*spatial_ids.get(id.as_str()).ok_or("dangling Semio model spatial parent")?)});}cycles(&parents,control,SqliteSnapshotPhase::ProjectSnapshot)?;
let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key_float("semio_model_document",1,&[Cell::Text(&self.schema)])?;
for(ordinal,node)in self.spatial.iter().enumerate(){let id=*entities.get(node.id.as_str()).ok_or("missing Semio spatial identity")?;p.insert_key_float("semio_model_entity",id,&[Cell::Integer(1),Cell::Text("spatial"),Cell::Integer(number(ordinal)?),Cell::Text(&node.id)])?;p.insert_key_float("semio_model_spatial",id,&[Cell::Text(match node.kind{SpatialKind::Site=>"site",SpatialKind::Building=>"building",SpatialKind::Storey=>"storey",SpatialKind::Space=>"space"}),Cell::Text(&node.name),parents[&id].map(Cell::Integer).unwrap_or(Cell::Null)])?;placement(id,node.placement,&mut p)?;}
for(ordinal,element)in self.elements.iter().enumerate(){let id=*entities.get(element.id.as_str()).ok_or("missing Semio element identity")?;let(class,name)=class(&element.class);p.insert_key_float("semio_model_entity",id,&[Cell::Integer(1),Cell::Text("element"),Cell::Integer(number(ordinal)?),Cell::Text(&element.id)])?;let spatial=match &element.spatial_id{None=>Cell::Null,Some(id)=>Cell::Integer(*spatial_ids.get(id.as_str()).ok_or("dangling Semio model element spatial reference")?)};p.insert_key_float("semio_model_element",id,&[Cell::Text(class),name.map(Cell::Text).unwrap_or(Cell::Null),spatial])?;placement(id,element.placement,&mut p)?;let(kind,target)=match &element.geometry{GeometryRef::None=>("none",Cell::Null),GeometryRef::Brep{brep_id}=>("brep",Cell::Text(brep_id)),GeometryRef::Mesh{mesh_id}=>("mesh",Cell::Text(mesh_id))};p.insert_key_float("semio_model_geometry_reference",id,&[Cell::Text(kind),target])?;
for(ordinal,pset)in element.psets.iter().enumerate(){let pset_id=p.insert_float("semio_model_property_set",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(&pset.name)])?;for(ordinal,property)in pset.properties.iter().enumerate(){let(kind,text,number_value,boolean)=match &property.value{PsetValue::Text{value}=>("text",Cell::Text(value),Cell::Null,Cell::Null),PsetValue::Number{value}=>("number",Cell::Null,Cell::Real(*value),Cell::Null),PsetValue::Boolean{value}=>("boolean",Cell::Null,Cell::Null,Cell::Integer(i64::from(*value)))};p.insert_float("semio_model_property",&[Cell::Integer(pset_id),Cell::Integer(number(ordinal)?),Cell::Text(&property.key),Cell::Text(kind),text,number_value,boolean])?;}}}
let mut ids=BTreeSet::new();for(ordinal,edge)in self.relations.iter().enumerate(){if !ids.insert(edge.id.as_str()){return Err("duplicate Semio model relation identity".into());}let(kind,label)=relation(&edge.kind);p.insert_float("semio_model_relation",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&edge.id),Cell::Text(kind),label.map(Cell::Text).unwrap_or(Cell::Null),Cell::Integer(*entities.get(edge.from.as_str()).ok_or("dangling Semio model relation source")?),Cell::Integer(*entities.get(edge.to.as_str()).ok_or("dangling Semio model relation target")?)])?;}p.finish()
}
fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(database, control, Self::SQLITE_SCHEMA) }
}

impl SemioModelSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {

control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,declared_schema,control.limits()).map_err(|error|error.to_string())?;let document=single_float_row(database,"semio_model_document")?;identity(document,2)?;if document.rowid!=1{return Err("invalid Semio model document identifier".into());}
let entities=rows(database,"semio_model_entity",5,control)?;let mut spatial_rows=rows(database,"semio_model_spatial",4,control)?;let mut element_rows=rows(database,"semio_model_element",4,control)?;let mut placements=rows(database,"semio_model_placement",11,control)?;let mut geometries=rows(database,"semio_model_geometry_reference",3,control)?;let mut names=BTreeMap::new();let mut native_ids=BTreeSet::new();let mut spatial_order=Vec::new();let mut element_order=Vec::new();for(&id,row)in &entities{if row.integer(1)?!=1||!native_ids.insert(row.text(4)?){return Err("invalid Semio model entity ownership or identity".into());}names.insert(id,row.text(4)?);match row.text(2)?{"spatial"=>spatial_order.push(*row),"element"=>element_order.push(*row),_=>return Err("unknown Semio model entity kind".into())}}
let mut parents=BTreeMap::new();for(&id,row)in &spatial_rows{parents.insert(id,optional_integer(*row,3)?);}cycles(&parents,control,SqliteSnapshotPhase::ReconstructSnapshot)?;
let mut psets=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();let mut properties=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();let mut pset_ids=BTreeSet::new();let mut completed=0usize;for row in float_rows(database,"semio_model_property_set",control)?{identity(row,4)?;if !element_rows.contains_key(&row.integer(1)?)||!pset_ids.insert(row.rowid){return Err("invalid Semio model property-set owner or identity".into());}row.integer(2)?;psets.entry(row.integer(1)?).or_default().push(row);completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut property_ids=BTreeSet::new();for row in float_rows(database,"semio_model_property",control)?{identity(row,8)?;if !pset_ids.contains(&row.integer(1)?)||!property_ids.insert(row.rowid){return Err("invalid Semio model property owner or identity".into());}row.integer(2)?;properties.entry(row.integer(1)?).or_default().push(row);completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut spatial=Vec::new();for entity in ordered(spatial_order,3)?{let row=spatial_rows.remove(&entity.rowid).ok_or("missing Semio model spatial detail")?;let parent_id=parents[&entity.rowid].map(|id|reconstruct_text(control,names.get(&id).ok_or("dangling Semio model spatial parent")?)).transpose()?;let kind=match row.text(1)?{"site"=>SpatialKind::Site,"building"=>SpatialKind::Building,"storey"=>SpatialKind::Storey,"space"=>SpatialKind::Space,_=>return Err("unknown Semio spatial kind".into())};spatial.push(SpatialNode{id:reconstruct_text(control,entity.text(4)?)?,kind,name:reconstruct_text(control,row.text(2)?)?,parent_id,placement:restore_placement(placements.remove(&entity.rowid).ok_or("missing spatial placement")?)?});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut elements=Vec::new();for entity in ordered(element_order,3)?{let row=element_rows.remove(&entity.rowid).ok_or("missing Semio model element detail")?;let other=row.optional_text(2)?;let class=match row.text(1)?{"wall"=>ElementClass::Wall,"slab"=>ElementClass::Slab,"column"=>ElementClass::Column,"beam"=>ElementClass::Beam,"door"=>ElementClass::Door,"window"=>ElementClass::Window,"roof"=>ElementClass::Roof,"stair"=>ElementClass::Stair,"furniture"=>ElementClass::Furniture,"other"=>ElementClass::Other{name:reconstruct_text(control,other.ok_or("missing custom Semio element class name")?)?},_=>return Err("unknown Semio model element class".into())};if row.text(1)?!="other"&&other.is_some(){return Err("unexpected custom Semio element class name".into());}let spatial_id=optional_integer(row,3)?.map(|id|if parents.contains_key(&id){reconstruct_text(control,names.get(&id).ok_or("dangling Semio element spatial reference")?)}else{Err("dangling Semio element spatial reference".into())}).transpose()?;let reference=geometries.remove(&entity.rowid).ok_or("missing Semio model geometry reference")?;let target=reference.optional_text(2)?;let geometry=match reference.text(1)?{"none" if target.is_none()=>GeometryRef::None,"brep"=>GeometryRef::Brep{brep_id:reconstruct_text(control,target.ok_or("missing Semio BRep geometry identity")?)?},"mesh"=>GeometryRef::Mesh{mesh_id:reconstruct_text(control,target.ok_or("missing Semio mesh geometry identity")?)?},_=>return Err("invalid Semio model geometry reference shape".into())};let mut native_psets=Vec::new();
for pset in ordered(psets.remove(&entity.rowid).unwrap_or_default(),2)?{let mut native_properties=Vec::new();for property in ordered(properties.remove(&pset.rowid).unwrap_or_default(),2)?{let value=match property.text(4)?{"text" if property.is_null(6)?&&property.is_null(7)?=>PsetValue::Text{value:reconstruct_text(control,property.text(5)?)?},"number" if property.is_null(5)?&&property.is_null(7)?=>PsetValue::Number{value:property.real(6)?},"boolean" if property.is_null(5)?&&property.is_null(6)?=>PsetValue::Boolean{value:match property.integer(7)?{0=>false,1=>true,_=>return Err("invalid Semio model boolean property".into())}},_=>return Err("invalid Semio model property variant shape".into())};native_properties.push(Property{key:reconstruct_text(control,property.text(3)?)?,value});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}native_psets.push(PropertySet{name:reconstruct_text(control,pset.text(3)?)?,properties:native_properties});}
elements.push(SemioModelElement{id:reconstruct_text(control,entity.text(4)?)?,class,placement:restore_placement(placements.remove(&entity.rowid).ok_or("missing element placement")?)?,geometry,spatial_id,psets:native_psets});}
if !spatial_rows.is_empty()||!element_rows.is_empty()||!placements.is_empty()||!geometries.is_empty(){return Err("orphan or contradictory Semio model entity detail".into());}let mut relations=Vec::new();let mut ids=BTreeSet::new();let mut native_ids=BTreeSet::new();for row in ordered_float_rows(database,"semio_model_relation",2,control)?{identity(row,8)?;if row.integer(1)?!=1||!ids.insert(row.rowid)||!native_ids.insert(row.text(3)?){return Err("invalid Semio model relation owner or identity".into());}let other=row.optional_text(5)?;let kind=match row.text(4)?{"aggregates"=>RelationKind::Aggregates,"contained_in"=>RelationKind::ContainedIn,"connects_to"=>RelationKind::ConnectsTo,"fills_void"=>RelationKind::FillsVoid,"voids_element"=>RelationKind::VoidsElement,"other"=>RelationKind::Other{label:reconstruct_text(control,other.ok_or("missing custom Semio relation label")?)?},_=>return Err("unknown Semio model relation kind".into())};if row.text(4)?!="other"&&other.is_some(){return Err("unexpected custom Semio model relation label".into());}relations.push(ModelRelation{id:reconstruct_text(control,row.text(3)?)?,kind,from:reconstruct_text(control,names.get(&row.integer(6)?).ok_or("dangling Semio model relation source")?)?,to:reconstruct_text(control,names.get(&row.integer(7)?).ok_or("dangling Semio model relation target")?)?});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,completed)?;Ok(Self{schema:reconstruct_text(control,document.text(1)?)?,spatial,elements,relations})
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_model_property"=>&[FloatColumn::Binary64(6)],"semio_model_placement"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioModelSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.entities(self.spatial.len())?;for spatial in &self.spatial{b.text(&spatial.id)?;b.text(&spatial.name)?;b.optional_text(spatial.parent_id.as_deref())?;b.scalars(11)?;}b.entities(self.elements.len())?;for element in &self.elements{b.text(&element.id)?;b.optional_text(element.spatial_id.as_deref())?;b.scalars(11)?;if let ElementClass::Other{name}=&element.class{b.text(name)?;}match &element.geometry{GeometryRef::None=>{},GeometryRef::Brep{brep_id}=>b.text(brep_id)?,GeometryRef::Mesh{mesh_id}=>b.text(mesh_id)?}b.entities(element.psets.len())?;for pset in &element.psets{b.text(&pset.name)?;b.entities(pset.properties.len())?;for property in &pset.properties{b.text(&property.key)?;match &property.value{PsetValue::Text{value}=>b.text(value)?,PsetValue::Number{..}|PsetValue::Boolean{..}=>b.scalars(1)?}}}}b.entities(self.relations.len())?;for relation in &self.relations{b.text(&relation.id)?;b.text(&relation.from)?;b.text(&relation.to)?;b.scalars(1)?;if let RelationKind::Other{label}=&relation.kind{b.text(label)?;}}Ok(())}
}
